            for f2 in perms:
                f = (f0, f1, f2)
                ok = all(
                    perm_compose(perm_inverse(f[u]), f[v]) == transitions[(u, v)]
                    for (u, v) in transitions
                )
                if ok:
                    found = f
    print(f"exhaustive search over all {len(perms) ** 3} labellings found a global "
          f"section: {found is not None}")


