"""
Cover-scale sweep: how the nerve, its Betti number, and certifiability change as
the overlap scale delta grows.

For a fixed set of anchors sampled around an annulus and a fixed continuous
score, we sweep the overlap scale delta and report at each scale:

  * the nerve's vertex/edge counts, component count and first Betti number
    dim H^1 = |E| - |V| + k  (the number of independent obstruction classes);
  * whether the anchors all carry the same decision (no sign holonomy);
  * whether uniform certification at radius delta survives, and if not, the
    explicit decision-boundary witness produced by bisection and its distance to
    the offending anchor.

The sweep exhibits the central trade-off of the theory: small delta gives a
disconnected nerve (many separate, weak guarantees), large delta gives a richly
looped nerve (many independent obstructions to audit) and eventually swallows
the decision boundary, at which point certification at that radius is provably
impossible.

Self-contained; no third-party dependencies.
"""

from __future__ import annotations

import math
from typing import Callable, Dict, List, Optional, Sequence, Tuple

Vector = Tuple[float, float]
Score = Callable[[Vector], float]
Edge = Tuple[int, int]


def linf_dist(a: Vector, b: Vector) -> float:
    return max(abs(a[0] - b[0]), abs(a[1] - b[1]))


def build_nerve(anchors: Sequence[Vector], delta: float) -> List[Edge]:
    n = len(anchors)
    return [(i, j) for i in range(n) for j in range(i + 1, n)
            if linf_dist(anchors[i], anchors[j]) <= delta + 1e-12]


def components(n: int, edges: Sequence[Edge]) -> int:
    parent = list(range(n))

    def find(a: int) -> int:
        while parent[a] != a:
            parent[a] = parent[parent[a]]
            a = parent[a]
        return a

    for i, j in edges:
        ri, rj = find(i), find(j)
        if ri != rj:
            parent[ri] = rj
    return len({find(v) for v in range(n)})


def find_flip(score: Score, anchors: Sequence[Vector],
              edges: Sequence[Edge]) -> Optional[Edge]:
    for i, j in edges:
        if score(anchors[i]) > 0 >= score(anchors[j]):
            return (i, j)
        if score(anchors[j]) > 0 >= score(anchors[i]):
            return (j, i)
    return None


def bisect(score: Score, u: Vector, v: Vector, iters: int = 60) -> Vector:
    lo, hi = 0.0, 1.0
    for _ in range(iters):
        mid = 0.5 * (lo + hi)
        p = (u[0] + mid * (v[0] - u[0]), u[1] + mid * (v[1] - u[1]))
        if score(p) > 0:
            lo = mid
        else:
            hi = mid
    return (u[0] + hi * (v[0] - u[0]), u[1] + hi * (v[1] - u[1]))


def true_certified_radius(score: Score, anchor: Vector, hi: float = 2.0,
                          iters: int = 40) -> float:
    """Largest r such that the sup-norm ball of radius r around `anchor` avoids
    the decision boundary, computed by bisection on r with a dense boundary scan."""
    sign0 = 1.0 if score(anchor) > 0 else -1.0

    def clean(r: float, samples: int = 240) -> bool:
        for t in range(samples):
            u = -r + 2 * r * t / (samples - 1)
            for p in ((anchor[0] + u, anchor[1] - r), (anchor[0] + u, anchor[1] + r),
                      (anchor[0] - r, anchor[1] + u), (anchor[0] + r, anchor[1] + u)):
                if sign0 * score(p) <= 0:
                    return False
        return True

    lo = 0.0
    for _ in range(iters):
        mid = 0.5 * (lo + hi)
        if clean(mid):
            lo = mid
        else:
            hi = mid
    return lo


def sweep(score: Score, anchors: Sequence[Vector],
          deltas: Sequence[float]) -> List[Dict[str, object]]:
    rows: List[Dict[str, object]] = []
    for delta in deltas:
        edges = build_nerve(anchors, delta)
        k = components(len(anchors), edges)
        flip = find_flip(score, anchors, edges)
        row: Dict[str, object] = {
            "delta": delta,
            "edges": len(edges),
            "components": k,
            "betti": len(edges) - len(anchors) + k,
            "certifiable": flip is None,
            "witness_distance": None,
        }
        if flip is not None:
            z = bisect(score, anchors[flip[0]], anchors[flip[1]])
            row["witness_distance"] = linf_dist(z, anchors[flip[0]])
            row["flip_edge"] = flip
        rows.append(row)
    return rows


def main() -> None:
    print(__doc__)

    def score(p: Vector) -> float:
        """Annulus: positive on the ring 0.5 < |p| < 1.26, negative inside/outside."""
        r2 = p[0] ** 2 + p[1] ** 2
        return (r2 - 0.25) * (1.6 - r2)

    outer = 12
    inner = 6
    anchors: List[Vector] = [
        (0.9 * math.cos(2 * math.pi * i / outer),
         0.9 * math.sin(2 * math.pi * i / outer))
        for i in range(outer)
    ] + [
        (0.35 * math.cos(2 * math.pi * i / inner),
         0.35 * math.sin(2 * math.pi * i / inner))
        for i in range(inner)
    ]

    print(f"{outer} anchors on the circle of radius 0.9 (inside the positive ring) and "
          f"{inner} anchors\non the circle of radius 0.35 (inside the negative hole).\n")
    print(f"{'delta':>7}{'|E|':>6}{'k':>4}{'beta_1':>8}{'certifiable':>13}"
          f"{'witness dist':>14}")
    deltas = [round(0.05 * i, 2) for i in range(1, 17)]
    for row in sweep(score, anchors, deltas):
        wd = row["witness_distance"]
        print(f"{row['delta']:>7.2f}{row['edges']:>6}{row['components']:>4}"
              f"{row['betti']:>8}{str(row['certifiable']):>13}"
              f"{'-' if wd is None else f'{wd:.4f}':>14}")

    r_true = true_certified_radius(score, anchors[0])
    print(f"\nExact certified radius of a single anchor (bisection on the ball radius): "
          f"{r_true:.4f}")
    print("Interpretation:")
    print("  * for delta below the connectivity threshold the nerve is disconnected: each")
    print("    component glues on its own, giving several separate guarantees;")
    print("  * once connected and while delta stays below the exact certified radius, the")
    print("    local certificates glue into ONE guarantee over the whole union of balls;")
    print("  * beyond that scale a sign flip appears along the nerve and bisection returns")
    print("    a decision-boundary point within delta of a named anchor, which refutes")
    print("    uniform certification at that radius. The Betti number column counts the")
    print("    independent loops that an audit must check at each scale.")


if __name__ == "__main__":
    main()

