"""Algorithm 1 — Nerve construction and the first Betti number of a cover.

Given anchors and an overlap scale delta, build the nerve graph and return the
number of independent obstruction classes dim H^1 = |E| - |V| + k.
"""

from __future__ import annotations

from typing import Dict, List, Sequence, Tuple

Vector = Tuple[float, ...]
Edge = Tuple[int, int]


def linf_dist(a: Vector, b: Vector) -> float:
    """Sup-norm distance."""
    return max(abs(x - y) for x, y in zip(a, b))


def build_nerve(anchors: Sequence[Vector], delta: float, tol: float = 1e-12) -> List[Edge]:
    """Edges of the nerve: pairs of anchors within L-infinity distance delta.

    Cost: O(N^2 d).  For large N replace the double loop by a uniform grid
    bucketing of side delta, giving O(N * 3^d) expected work.
    """
    n = len(anchors)
    return [(i, j) for i in range(n) for j in range(i + 1, n)
            if linf_dist(anchors[i], anchors[j]) <= delta + tol]


class UnionFind:
    """Disjoint-set forest with path halving; near-constant amortised cost."""

    def __init__(self, n: int) -> None:
        self.parent: List[int] = list(range(n))

    def find(self, a: int) -> int:
        while self.parent[a] != a:
            self.parent[a] = self.parent[self.parent[a]]
            a = self.parent[a]
        return a

    def union(self, a: int, b: int) -> bool:
        ra, rb = self.find(a), self.find(b)
        if ra == rb:
            return False
        self.parent[ra] = rb
        return True


def component_count(n_vertices: int, edges: Sequence[Edge]) -> int:
    """Number of connected components of the nerve."""
    uf = UnionFind(n_vertices)
    for i, j in edges:
        uf.union(i, j)
    return len({uf.find(v) for v in range(n_vertices)})


def first_betti_number(n_vertices: int, edges: Sequence[Edge]) -> int:
    """dim H^1 = |E| - |V| + k: the number of independent obstruction classes."""
    return len(edges) - n_vertices + component_count(n_vertices, edges)


def audit_cover(anchors: Sequence[Vector], delta: float) -> Dict[str, int]:
    """Full combinatorial audit of a cover at overlap scale delta."""
    edges = build_nerve(anchors, delta)
    n = len(anchors)
    k = component_count(n, edges)
    return {
        "vertices": n,
        "edges": len(edges),
        "components": k,
        "betti_1": len(edges) - n + k,
        "is_forest": int(len(edges) - n + k == 0),
    }


if __name__ == "__main__":
    ring = [(0.75 * __import__("math").cos(2 * 3.141592653589793 * i / 9),
             0.75 * __import__("math").sin(2 * 3.141592653589793 * i / 9))
            for i in range(9)]
    print(audit_cover(ring, 0.55))

"""Algorithm 2 — Fundamental-cycle holonomy audit.

Extract a basis of the cycle space of the nerve (one fundamental cycle per
non-tree edge of a spanning forest) and evaluate the holonomy of a 1-cochain on
each.  By the discrete Poincare lemma, the cochain glues if and only if all these
holonomies vanish; the number of cycles is the first Betti number.
"""

from __future__ import annotations

from typing import Dict, List, Optional, Sequence, Tuple

Edge = Tuple[int, int]
Cochain = Dict[Edge, float]


def adjacency(n_vertices: int, edges: Sequence[Edge]) -> Dict[int, List[int]]:
    adj: Dict[int, List[int]] = {i: [] for i in range(n_vertices)}
    for i, j in edges:
        adj[i].append(j)
        adj[j].append(i)
    return adj


def spanning_forest(n_vertices: int, edges: Sequence[Edge]) -> Tuple[List[Edge], List[Edge]]:
    """Split edges into (forest edges, non-tree edges).  Cost O(|E| a(|V|))."""
    parent = list(range(n_vertices))

    def find(a: int) -> int:
        while parent[a] != a:
            parent[a] = parent[parent[a]]
            a = parent[a]
        return a

    tree: List[Edge] = []
    extra: List[Edge] = []
    for e in edges:
        ra, rb = find(e[0]), find(e[1])
        if ra == rb:
            extra.append(e)
        else:
            parent[ra] = rb
            tree.append(e)
    return tree, extra


def tree_path(n_vertices: int, tree: Sequence[Edge], src: int, dst: int) -> Optional[List[int]]:
    """Unique path src -> dst inside the spanning forest (breadth-first)."""
    adj = adjacency(n_vertices, tree)
    prev: Dict[int, int] = {src: src}
    frontier = [src]
    while frontier:
        nxt: List[int] = []
        for u in frontier:
            for w in adj[u]:
                if w not in prev:
                    prev[w] = u
                    nxt.append(w)
        frontier = nxt
    if dst not in prev:
        return None
    out = [dst]
    while out[-1] != src:
        out.append(prev[out[-1]])
    return list(reversed(out))


def fundamental_cycles(n_vertices: int, edges: Sequence[Edge]) -> List[List[int]]:
    """A basis of the cycle space: one closed walk per non-tree edge."""
    tree, extra = spanning_forest(n_vertices, edges)
    cycles: List[List[int]] = []
    for u, v in extra:
        p = tree_path(n_vertices, tree, v, u)
        if p is not None:
            cycles.append([u] + p)
    return cycles


def holonomy(cochain: Cochain, walk: Sequence[int]) -> float:
    """Sum of the antisymmetric discrepancy along a walk (c_ji = -c_ij)."""
    total = 0.0
    for u, v in zip(walk, walk[1:]):
        if (u, v) in cochain:
            total += cochain[(u, v)]
        elif (v, u) in cochain:
            total -= cochain[(v, u)]
        else:
            raise KeyError(f"edge {(u, v)} is not in the nerve")
    return total


def audit_holonomies(n_vertices: int, edges: Sequence[Edge], cochain: Cochain
                     ) -> List[Tuple[List[int], float]]:
    """Complete list of independent obstructions with their holonomies."""
    return [(cyc, holonomy(cochain, cyc)) for cyc in fundamental_cycles(n_vertices, edges)]


def glues(n_vertices: int, edges: Sequence[Edge], cochain: Cochain,
          tol: float = 1e-9) -> bool:
    """Discrete Poincare lemma: gluing <=> vanishing holonomy on a cycle basis."""
    return all(abs(h) <= tol for _, h in audit_holonomies(n_vertices, edges, cochain))


if __name__ == "__main__":
    edges: List[Edge] = [(0, 1), (1, 2), (2, 3), (0, 3), (0, 2)]
    c: Cochain = {(0, 1): 1.0, (1, 2): 2.0, (2, 3): -0.5, (0, 3): 2.5, (0, 2): 3.0}
    for cyc, h in audit_holonomies(4, edges, c):
        print(f"cycle {cyc}: holonomy {h:+.3f}")
    print("glues:", glues(4, edges, c))

"""Algorithm 3 — Certificate gluing, or refutation with an explicit witness.

Given a continuous score, anchors, and an overlap scale delta, either
  (a) return a single global certificate valid on the union of all the
      L-infinity balls of radius delta (Gluing Theorem), or
  (b) return an explicit point z on the decision boundary with
      ||z - x_u||_inf <= delta for a named anchor u, which refutes certification
      of that anchor at radius delta (Holonomy Obstruction Theorem).
"""

from __future__ import annotations

from typing import Callable, Dict, List, Optional, Sequence, Tuple

Vector = Tuple[float, ...]
Score = Callable[[Vector], float]
Edge = Tuple[int, int]


def linf_dist(a: Vector, b: Vector) -> float:
    return max(abs(x - y) for x, y in zip(a, b))


def build_nerve(anchors: Sequence[Vector], delta: float) -> List[Edge]:
    n = len(anchors)
    return [(i, j) for i in range(n) for j in range(i + 1, n)
            if linf_dist(anchors[i], anchors[j]) <= delta + 1e-12]


def is_connected(n_vertices: int, edges: Sequence[Edge]) -> bool:
    if n_vertices == 0:
        return False
    adj: Dict[int, List[int]] = {i: [] for i in range(n_vertices)}
    for i, j in edges:
        adj[i].append(j)
        adj[j].append(i)
    seen = {0}
    stack = [0]
    while stack:
        u = stack.pop()
        for w in adj[u]:
            if w not in seen:
                seen.add(w)
                stack.append(w)
    return len(seen) == n_vertices


def find_flip_edge(score: Score, anchors: Sequence[Vector],
                   edges: Sequence[Edge]) -> Optional[Edge]:
    """Locate an overlap across which the decision changes (oriented + -> -)."""
    for i, j in edges:
        if score(anchors[i]) > 0 >= score(anchors[j]):
            return (i, j)
        if score(anchors[j]) > 0 >= score(anchors[i]):
            return (j, i)
    return None


def boundary_witness(score: Score, u: Vector, v: Vector, iters: int = 60) -> Vector:
    """Intermediate value theorem by bisection: a zero of the score on [u, v].

    Requires score(u) > 0 >= score(v).  After k steps the bracket has width
    2^-k ||v - u||, so the cost is O(log(1/eta)) score evaluations for accuracy
    eta, and the returned point satisfies ||z - u||_inf <= ||v - u||_inf.
    """
    lo, hi = 0.0, 1.0
    for _ in range(iters):
        mid = 0.5 * (lo + hi)
        p = tuple(a + mid * (b - a) for a, b in zip(u, v))
        if score(p) > 0:
            lo = mid
        else:
            hi = mid
    return tuple(a + hi * (b - a) for a, b in zip(u, v))


def glue_or_refute(score: Score, anchors: Sequence[Vector], delta: float
                   ) -> Dict[str, object]:
    """Run the full pipeline and return a structured verdict."""
    edges = build_nerve(anchors, delta)
    connected = is_connected(len(anchors), edges)
    flip = find_flip_edge(score, anchors, edges)

    if flip is None:
        tau = 1 if score(anchors[0]) > 0 else -1
        return {
            "status": "glued" if connected else "glued-per-component",
            "global_sign": tau,
            "connected": connected,
            "edges": edges,
            "claim": ("every y with ||y - x_i||_inf <= delta, for any anchor i, "
                      f"satisfies sign(s(y)) = {tau:+d}"),
        }

    u_idx, v_idx = flip
    z = boundary_witness(score, anchors[u_idx], anchors[v_idx])
    return {
        "status": "refuted",
        "flip_edge": flip,
        "witness": z,
        "witness_score": score(z),
        "witness_distance": linf_dist(z, anchors[u_idx]),
        "connected": connected,
        "edges": edges,
        "claim": (f"no sign certifies anchor {u_idx} at radius {delta}: "
                  "an explicit decision-boundary point lies within delta of it"),
    }


if __name__ == "__main__":
    def s(p: Vector) -> float:
        return 0.7 - p[0]

    anchors: List[Vector] = [(0.3 * i, 0.0) for i in range(5)]
    result = glue_or_refute(s, anchors, 0.3)
    for key, value in result.items():
        print(f"{key:>18}: {value}")

"""Algorithm 4 — Harmonic defect minimisation on a cyclic cover.

On a loop of n+1 regions with real overlap discrepancies g, compute in O(n):
  * the holonomy H = sum g_i (the complete invariant of the cohomology class);
  * the exact minimal uniform certificate mismatch |H| / (n+1);
  * the harmonic (constant-defect) representative g_i - H/(n+1);
  * the optimal global potential realising the minimum.
"""

from __future__ import annotations

from typing import Dict, List, Sequence


def holonomy(g: Sequence[float]) -> float:
    """Total loop sum: zero exactly when the local data glues."""
    return sum(g)


def minimal_defect(g: Sequence[float]) -> float:
    """Defect Theorem: the least achievable uniform mismatch is |H| / (n+1)."""
    return abs(sum(g)) / len(g)


def harmonic_representative(g: Sequence[float]) -> List[float]:
    """Subtract the mean: the unique constant-defect representative of the class."""
    shift = sum(g) / len(g)
    return [gi - shift for gi in g]


def optimal_potential(g: Sequence[float]) -> List[float]:
    """Discrete primitive of the harmonic representative: the minimiser."""
    h = harmonic_representative(g)
    f = [0.0]
    for hi in h[:-1]:
        f.append(f[-1] + hi)
    return f


def defect_profile(g: Sequence[float]) -> Dict[str, object]:
    """Complete report for a cyclic cover."""
    n = len(g)
    f = optimal_potential(g)
    mismatch = [abs((f[(i + 1) % n] - f[i]) - g[i]) for i in range(n)]
    return {
        "n_regions": n,
        "holonomy": holonomy(g),
        "minimal_defect": minimal_defect(g),
        "glues_exactly": abs(holonomy(g)) < 1e-12,
        "harmonic_representative": harmonic_representative(g),
        "optimal_potential": f,
        "per_overlap_mismatch": mismatch,
        "mismatch_is_constant": max(mismatch) - min(mismatch) < 1e-12,
    }


if __name__ == "__main__":
    for g in ([1.0, -1.0, 0.5, -0.5], [0.3, -1.2, 2.0, 0.4, -0.1]):
        report = defect_profile(g)
        print(f"g = {g}")
        for key, value in report.items():
            print(f"    {key:>26}: {value}")

"""Algorithm 5 — Nonabelian permutation-monodromy audit for k-class covers.

For a multi-class classifier the datum on an overlap is a relabelling of the k
classes.  Holonomy becomes an ordered product of permutations, and a global
labelling exists if and only if the monodromy of every independent loop is the
identity.  The algorithm returns the monodromy of each fundamental cycle and,
when all are trivial, the global relabelling reconstructed by transport along a
spanning tree.
"""

from __future__ import annotations

from typing import Dict, List, Optional, Sequence, Tuple

Perm = Tuple[int, ...]
Edge = Tuple[int, int]


def identity(k: int) -> Perm:
    return tuple(range(k))


def compose(p: Perm, q: Perm) -> Perm:
    """Apply p first, then q."""
    return tuple(q[p[i]] for i in range(len(p)))


def inverse(p: Perm) -> Perm:
    out = [0] * len(p)
    for i, pi in enumerate(p):
        out[pi] = i
    return tuple(out)


def transition(transitions: Dict[Edge, Perm], u: int, v: int) -> Perm:
    """Oriented transition, using c_vu = (c_uv)^{-1}."""
    if (u, v) in transitions:
        return transitions[(u, v)]
    if (v, u) in transitions:
        return inverse(transitions[(v, u)])
    raise KeyError(f"no transition on the overlap {(u, v)}")


def monodromy(transitions: Dict[Edge, Perm], walk: Sequence[int], k: int) -> Perm:
    """Ordered product of the relabellings crossed along a walk."""
    out = identity(k)
    for u, v in zip(walk, walk[1:]):
        out = compose(out, transition(transitions, u, v))
    return out


def spanning_tree(n_vertices: int, edges: Sequence[Edge]) -> Tuple[List[Edge], List[Edge]]:
    parent = list(range(n_vertices))

    def find(a: int) -> int:
        while parent[a] != a:
            parent[a] = parent[parent[a]]
            a = parent[a]
        return a

    tree: List[Edge] = []
    extra: List[Edge] = []
    for e in edges:
        ra, rb = find(e[0]), find(e[1])
        if ra == rb:
            extra.append(e)
        else:
            parent[ra] = rb
            tree.append(e)
    return tree, extra


def transport_labelling(n_vertices: int, tree: Sequence[Edge],
                        transitions: Dict[Edge, Perm], k: int, base: int = 0
                        ) -> Dict[int, Perm]:
    """Global relabelling built by transporting from `base` along the tree."""
    adj: Dict[int, List[int]] = {i: [] for i in range(n_vertices)}
    for i, j in tree:
        adj[i].append(j)
        adj[j].append(i)
    f: Dict[int, Perm] = {base: identity(k)}
    stack = [base]
    while stack:
        u = stack.pop()
        for w in adj[u]:
            if w not in f:
                f[w] = compose(f[u], transition(transitions, u, w))
                stack.append(w)
    return f


def audit_multiclass(n_vertices: int, edges: Sequence[Edge],
                     transitions: Dict[Edge, Perm], k: int
                     ) -> Dict[str, object]:
    """Return the monodromy of every independent loop and, if all are trivial,
    an explicit global labelling."""
    tree, extra = spanning_tree(n_vertices, edges)
    labels = transport_labelling(n_vertices, tree, transitions, k)
    obstructions: List[Tuple[Edge, Perm]] = []
    for (u, v) in extra:
        # monodromy of the fundamental cycle of the non-tree edge (u,v)
        loop = compose(compose(labels[u], transition(transitions, u, v)),
                       inverse(labels[v]))
        if loop != identity(k):
            obstructions.append(((u, v), loop))
    consistent = not obstructions
    return {
        "independent_loops": len(extra),
        "obstructions": obstructions,
        "globally_consistent": consistent,
        "global_labelling": labels if consistent else None,
    }


if __name__ == "__main__":
    k = 3
    swap01: Perm = (1, 0, 2)
    edges: List[Edge] = [(0, 1), (1, 2), (0, 2)]
    transitions: Dict[Edge, Perm] = {(0, 1): swap01, (1, 2): swap01, (0, 2): swap01}
    report = audit_multiclass(3, edges, transitions, k)
    print("monodromy around 0 -> 1 -> 2 -> 0:", monodromy(transitions, [0, 1, 2, 0], k))
    for key, value in report.items():
        print(f"{key:>22}: {value}")

modules.demo:
"""
Certified Adversarial Robustness as a Cohomological Invariant of a Cover
=========================================================================

Self-contained numerical demonstration of the results:

  1. Overlap compatibility: certification forces signs to agree on overlaps.
  2. Gluing theorem: on a connected nerve, local L-infinity certificates
     assemble into one global certificate over the union of the balls.
  3. Holonomy obstruction: a sign flip along a walk yields, by the
     intermediate value theorem, an explicit decision-boundary point within
     the overlap scale of a named anchor -- capping the certified radius.
  4. Betti number law: dim H^1 = |E| - |V| + k for a nerve with k components;
     zero exactly for forests.
  5. Loop cohomology and the defect theorem: minimal uniform certificate
     mismatch on a cycle of n+1 regions equals |sum g| / (n+1), attained.
  6. Discrete torus: two independent holonomies, dim H^1 = 2.
  7. Z/2 parity obstruction and nonabelian (permutation) monodromy.
  8. Certified radius transfer: r_j >= r_i0 - D * eps.

Run:  python demo.py          (no third-party dependencies)
"""

from __future__ import annotations

import itertools
import math
from typing import Callable, Dict, Iterable, List, Optional, Sequence, Tuple

Vector = Tuple[float, ...]
Score = Callable[[Vector], float]
Edge = Tuple[int, int]


# ---------------------------------------------------------------------------
# Basic geometry
# ---------------------------------------------------------------------------

def linf_norm(v: Vector) -> float:
    """Sup norm of a vector."""
    return max(abs(c) for c in v) if v else 0.0


def linf_dist(a: Vector, b: Vector) -> float:
    """L-infinity distance between two points."""
    return linf_norm(tuple(x - y for x, y in zip(a, b)))


def lerp(u: Vector, v: Vector, t: float) -> Vector:
    """Point u + t (v - u) on the segment joining u to v."""
    return tuple(a + t * (b - a) for a, b in zip(u, v))


# ---------------------------------------------------------------------------
# 1. Local sections of the decision sheaf: sign certificates
# ---------------------------------------------------------------------------

def sign_certified(
    score: Score,
    anchor: Vector,
    radius: float,
    sigma: int,
    samples: int = 4000,
    seed: int = 0,
) -> bool:
    """Empirical test of SC(s, x, rho, sigma): sigma * s(y) > 0 for all y in the
    closed sup-norm ball of radius `radius` around `anchor`.

    This is a Monte-Carlo *falsifier*: it returns False as soon as a violating
    sample is found, and True if no violation is seen.  It stands in for a real
    certifier (interval propagation, randomised smoothing, ...) in this demo.
    """
    rng = _Lcg(seed)
    if sigma * score(anchor) <= 0:
        return False
    d = len(anchor)
    for _ in range(samples):
        y = tuple(anchor[k] + radius * (2.0 * rng.next() - 1.0) for k in range(d))
        if sigma * score(y) <= 0:
            return False
    return True


class _Lcg:
    """Tiny deterministic linear congruential generator (keeps demo dependency-free)."""

    def __init__(self, seed: int = 0) -> None:
        self.state = (seed * 6364136223846793005 + 1442695040888963407) % (2 ** 64)

    def next(self) -> float:
        self.state = (self.state * 6364136223846793005 + 1442695040888963407) % (2 ** 64)
        return (self.state >> 11) / float(1 << 53)


# ---------------------------------------------------------------------------
# 2. The nerve of a cover
# ---------------------------------------------------------------------------

def build_nerve(anchors: Sequence[Vector], delta: float, tol: float = 1e-9) -> List[Edge]:
    """Edges {i,j} of the nerve: anchors within L-infinity distance `delta`
    (up to a floating-point tolerance)."""
    return [
        (i, j)
        for i in range(len(anchors))
        for j in range(i + 1, len(anchors))
        if linf_dist(anchors[i], anchors[j]) <= delta + tol
    ]


def adjacency(n_vertices: int, edges: Iterable[Edge]) -> Dict[int, List[int]]:
    adj: Dict[int, List[int]] = {i: [] for i in range(n_vertices)}
    for (i, j) in edges:
        adj[i].append(j)
        adj[j].append(i)
    return adj


def connected_components(n_vertices: int, edges: Sequence[Edge]) -> List[List[int]]:
    """Union-find components of the nerve graph."""
    parent = list(range(n_vertices))

    def find(a: int) -> int:
        while parent[a] != a:
            parent[a] = parent[parent[a]]
            a = parent[a]
        return a

    for (i, j) in edges:
        ri, rj = find(i), find(j)
        if ri != rj:
            parent[ri] = rj

    buckets: Dict[int, List[int]] = {}
    for v in range(n_vertices):
        buckets.setdefault(find(v), []).append(v)
    return list(buckets.values())


def first_betti_number(n_vertices: int, edges: Sequence[Edge]) -> int:
    """dim H^1 = |E| - |V| + k  (Betti Number Law)."""
    k = len(connected_components(n_vertices, edges))
    return len(edges) - n_vertices + k


def is_forest(n_vertices: int, edges: Sequence[Edge]) -> bool:
    return first_betti_number(n_vertices, edges) == 0


def walk_between(n_vertices: int, edges: Sequence[Edge], src: int, dst: int
                 ) -> Optional[List[int]]:
    """A vertex path src -> ... -> dst in the nerve, or None if unreachable."""
    adj = adjacency(n_vertices, edges)
    prev: Dict[int, int] = {src: src}
    frontier = [src]
    while frontier:
        nxt: List[int] = []
        for u in frontier:
            for w in adj[u]:
                if w not in prev:
                    prev[w] = u
                    nxt.append(w)
        frontier = nxt
    if dst not in prev:
        return None
    path = [dst]
    while path[-1] != src:
        path.append(prev[path[-1]])
    return list(reversed(path))


def nerve_eccentricity(n_vertices: int, edges: Sequence[Edge], base: int) -> int:
    """Maximal graph distance from `base` (the D of the radius-transfer theorem)."""
    adj = adjacency(n_vertices, edges)
    dist = {base: 0}
    frontier = [base]
    while frontier:
        nxt = []
        for u in frontier:
            for w in adj[u]:
                if w not in dist:
                    dist[w] = dist[u] + 1
                    nxt.append(w)
        frontier = nxt
    return max(dist.values())


# ---------------------------------------------------------------------------
# 3. Holonomy of a real 1-cochain, fundamental cycles
# ---------------------------------------------------------------------------

def holonomy_along(cochain: Dict[Edge, float], path: Sequence[int]) -> float:
    """Sum of the antisymmetric discrepancy c along a vertex path."""
    total = 0.0
    for u, v in zip(path, path[1:]):
        if (u, v) in cochain:
            total += cochain[(u, v)]
        elif (v, u) in cochain:
            total -= cochain[(v, u)]
        else:
            raise KeyError(f"edge {(u, v)} not in the nerve")
    return total


def spanning_forest(n_vertices: int, edges: Sequence[Edge]) -> Tuple[List[Edge], List[Edge]]:
    """Split the edges into (tree edges, non-tree edges)."""
    parent = list(range(n_vertices))

    def find(a: int) -> int:
        while parent[a] != a:
            parent[a] = parent[parent[a]]
            a = parent[a]
        return a

    tree: List[Edge] = []
    extra: List[Edge] = []
    for e in edges:
        ri, rj = find(e[0]), find(e[1])
        if ri == rj:
            extra.append(e)
        else:
            parent[ri] = rj
            tree.append(e)
    return tree, extra


def fundamental_cycles(n_vertices: int, edges: Sequence[Edge]) -> List[List[int]]:
    """One closed walk per independent cycle: a basis of the cycle space.
    Their number equals the first Betti number."""
    tree, extra = spanning_forest(n_vertices, edges)
    cycles: List[List[int]] = []
    for (u, v) in extra:
        path = walk_between(n_vertices, tree, v, u)
        if path is not None:
            cycles.append([u] + path)  # u -> v -> ... -> u
    return cycles


def is_coboundary(n_vertices: int, edges: Sequence[Edge],
                  cochain: Dict[Edge, float], tol: float = 1e-9) -> bool:
    """Discrete Poincare lemma: c glues iff all fundamental cycles have zero
    holonomy (which implies zero holonomy on *every* closed walk)."""
    return all(abs(holonomy_along(cochain, cyc)) <= tol
               for cyc in fundamental_cycles(n_vertices, edges))


def potential_from_cochain(n_vertices: int, edges: Sequence[Edge],
                           cochain: Dict[Edge, float], base: int = 0
                           ) -> Dict[int, float]:
    """Global potential f with c_ij = f_j - f_i, built by integrating along a
    spanning tree from `base` (valid when the holonomy vanishes)."""
    tree, _ = spanning_forest(n_vertices, edges)
    adj = adjacency(n_vertices, tree)
    f: Dict[int, float] = {base: 0.0}
    frontier = [base]
    while frontier:
        nxt = []
        for u in frontier:
            for w in adj[u]:
                if w not in f:
                    f[w] = f[u] + holonomy_along(cochain, [u, w])
                    nxt.append(w)
        frontier = nxt
    return f


# ---------------------------------------------------------------------------
# 4. Adversarial witness: locate the flip, then bisect
# ---------------------------------------------------------------------------

def find_sign_flip_edge(score: Score, anchors: Sequence[Vector],
                        path: Sequence[int]) -> Optional[Edge]:
    """Along a walk with s(start) > 0 and s(end) <= 0, return the single overlap
    across which positivity is lost."""
    for u, v in zip(path, path[1:]):
        if score(anchors[u]) > 0 >= score(anchors[v]):
            return (u, v)
    return None


def boundary_point_by_bisection(score: Score, u: Vector, v: Vector,
                                iters: int = 60) -> Vector:
    """Intermediate value witness: a point z on [u,v] with s(z) ~ 0, given
    s(u) > 0 >= s(v).  Distance to u is at most ||v - u||."""
    lo, hi = 0.0, 1.0  # s(lerp(lo)) > 0 >= s(lerp(hi))
    for _ in range(iters):
        mid = 0.5 * (lo + hi)
        if score(lerp(u, v, mid)) > 0:
            lo = mid
        else:
            hi = mid
    return lerp(u, v, hi)


# ---------------------------------------------------------------------------
# 5. Loop nerve: cohomology and the defect theorem
# ---------------------------------------------------------------------------

def loop_holonomy(g: Sequence[float]) -> float:
    return sum(g)


def loop_is_coboundary(g: Sequence[float], tol: float = 1e-9) -> bool:
    return abs(loop_holonomy(g)) <= tol


def loop_minimal_defect(g: Sequence[float]) -> float:
    """Defect theorem: min over potentials f of max_i |(f_{i+1}-f_i) - g_i|
    equals |sum g| / (n+1)."""
    return abs(sum(g)) / len(g)


def harmonic_representative(g: Sequence[float]) -> List[float]:
    """g minus its mean: the unique constant-defect (harmonic) representative."""
    h = sum(g) / len(g)
    return [gi - h for gi in g]


def loop_potential(g: Sequence[float]) -> List[float]:
    """Discrete primitive f_k = sum_{j<k} g_j (a genuine potential iff sum g = 0)."""
    f = [0.0]
    for gi in g[:-1]:
        f.append(f[-1] + gi)
    return f


def loop_defect_numeric(g: Sequence[float], iters: int = 40000) -> float:
    """Independent numerical check of the defect theorem: minimise the convex,
    piecewise-linear objective  F(f) = max_i |(f_{i+1} - f_i) - g_i|  over all
    potentials f (with f_0 pinned to 0), by smoothed gradient descent with an
    annealed log-sum-exp temperature.  Converges to |sum g| / (n+1)."""
    n = len(g)
    f = [0.0] * n

    def defect(fv: Sequence[float]) -> float:
        return max(abs((fv[(i + 1) % n] - fv[i]) - g[i]) for i in range(n))

    best = defect(f)
    for t in range(iters):
        beta = 5.0 + 300.0 * t / iters
        step = 0.2 / (1.0 + 0.01 * t)
        d = [(f[(i + 1) % n] - f[i]) - g[i] for i in range(n)]
        peak = max(abs(x) for x in d)
        weights = [math.exp(beta * (abs(x) - peak)) for x in d]
        total = sum(weights)
        grad = [0.0] * n
        for i in range(n):
            coeff = (weights[i] / total) * (1.0 if d[i] >= 0 else -1.0)
            grad[(i + 1) % n] += coeff
            grad[i] -= coeff
        f = [f[k] - step * grad[k] if k > 0 else 0.0 for k in range(n)]
        best = min(best, defect(f))
    return best


# ---------------------------------------------------------------------------
# 6. Discrete torus nerve
# ---------------------------------------------------------------------------

def torus_is_flat(h: List[List[float]], v: List[List[float]], tol: float = 1e-9) -> bool:
    """Plaquette condition h[a][b] + v[a+1][b] = v[a][b] + h[a][b+1]."""
    m, n = len(h), len(h[0])
    return all(
        abs(h[a][b] + v[(a + 1) % m][b] - v[a][b] - h[a][(b + 1) % n]) <= tol
        for a in range(m) for b in range(n)
    )


def torus_row_holonomy(h: List[List[float]], b: int) -> float:
    return sum(h[a][b] for a in range(len(h)))


def torus_col_holonomy(v: List[List[float]], a: int) -> float:
    return sum(v[a][b] for b in range(len(v[0])))


def torus_potential(h: List[List[float]], v: List[List[float]]) -> List[List[float]]:
    """f(a,b) = sum_{a'<a} h(a',0) + sum_{b'<b} v(a,b'); a genuine potential iff
    the cochain is flat and both holonomies vanish."""
    m, n = len(h), len(h[0])
    f = [[0.0] * n for _ in range(m)]
    for a in range(m):
        base = sum(h[ap][0] for ap in range(a))
        for b in range(n):
            f[a][b] = base + sum(v[a][bp] for bp in range(b))
    return f


# ---------------------------------------------------------------------------
# 7. Z/2 parity and nonabelian permutation monodromy
# ---------------------------------------------------------------------------

def parity_obstruction(flips: Sequence[int]) -> bool:
    """True iff the loop of label flips admits NO globally consistent labelling."""
    return sum(flips) % 2 == 1


Perm = Tuple[int, ...]


def perm_compose(p: Perm, q: Perm) -> Perm:
    """(p then q): apply p first."""
    return tuple(q[p[i]] for i in range(len(p)))


def perm_inverse(p: Perm) -> Perm:
    inv = [0] * len(p)
    for i, pi in enumerate(p):
        inv[pi] = i
    return tuple(inv)


def perm_monodromy(transitions: Dict[Edge, Perm], cycle: Sequence[int], k: int) -> Perm:
    """Ordered product of relabellings around a closed walk."""
    out: Perm = tuple(range(k))
    for u, v in zip(cycle, cycle[1:]):
        if (u, v) in transitions:
            step = transitions[(u, v)]
        elif (v, u) in transitions:
            step = perm_inverse(transitions[(v, u)])
        else:
            raise KeyError(f"no transition on {(u, v)}")
        out = perm_compose(out, step)
    return out


